#[derive(Clone, Debug, PartialEq, Eq)]
pub enum FieldError {
    EmptyName,
    Malformed,
    Duplicate,
}

pub fn read_tagged_field(input: &str, name: &str) -> Result<Option<String>, FieldError> {
    if name.is_empty() {
        return Err(FieldError::EmptyName);
    }

    let bytes = input.as_bytes();
    let mut pos = 0;
    let mut result: Option<String> = None;

    while pos < bytes.len() {
        if bytes[pos] != b'[' {
            pos += 1;
            continue;
        }
        let starts_delimiter = bytes.get(pos + 1) == Some(&b'/')
            || bytes.get(pos + 1).is_some_and(u8::is_ascii_alphabetic);
        if !starts_delimiter {
            pos += 1;
            continue;
        }

        let open_end = input[pos + 1..]
            .find(']')
            .map(|offset| pos + 1 + offset)
            .ok_or(FieldError::Malformed)?;
        let open_name = &input[pos + 1..open_end];
        if open_name.is_empty()
            || open_name.starts_with('/')
            || !open_name.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_')
        {
            return Err(FieldError::Malformed);
        }

        let close = format!("[/{open_name}]");
        let content_start = open_end + 1;
        let relative_end = input[content_start..]
            .find(&close)
            .ok_or(FieldError::Malformed)?;
        let content_end = content_start + relative_end;
        let content = &input[content_start..content_end];

        if content.as_bytes().windows(2).any(|w| {
            w[0] == b'[' && (w[1] == b'/' || w[1].is_ascii_alphabetic())
        }) {
            return Err(FieldError::Malformed);
        }

        if open_name == name {
            if result.is_some() {
                return Err(FieldError::Duplicate);
            }
            result = Some(content.to_string());
        }
        pos = content_end + close.len();
    }

    Ok(result)
}
